-- ============================================================
-- 猜地图 map 项目：主题种子 POI 导入（线上执行）
-- 生成日期: 2026-08-10
-- 共 751 条，覆盖 8 个主题
-- 说明: 幂等脚本，先清理这 8 个主题再重新插入，可重复执行
-- 依赖: pois 表需已含 source 字段（见 seed_pois.sql 的 DDL 部分）
-- ============================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 清理既有主题数据（8 个主题）
-- 先断开历史对局对将被删除 POI 的引用（target_poi_id 可空，避免外键约束失败）
UPDATE `game_records` gr
JOIN `pois` p ON gr.target_poi_id = p.id
SET gr.target_poi_id = NULL
WHERE p.category IN ('university_211', 'scenic_5a', 'peak_famous', 'lake_famous', 'airport_major', 'historic_city', 'museum_l1', 'unesco_whs');

UPDATE `pk_games` pg
JOIN `pois` p ON pg.target_poi_id = p.id
SET pg.target_poi_id = NULL
WHERE p.category IN ('university_211', 'scenic_5a', 'peak_famous', 'lake_famous', 'airport_major', 'historic_city', 'museum_l1', 'unesco_whs');

DELETE FROM `pois` WHERE `category` IN ('university_211', 'scenic_5a', 'peak_famous', 'lake_famous', 'airport_major', 'historic_city', 'museum_l1', 'unesco_whs');

-- 插入 751 条主题种子








COMMIT;

-- 校验：应等于 751
SELECT category, COUNT(*) FROM `pois` WHERE `category` IN ('university_211', 'scenic_5a', 'peak_famous', 'lake_famous', 'airport_major', 'historic_city', 'museum_l1', 'unesco_whs') GROUP BY category;
